<div class="page-head"><div><h1>Audit log</h1><p class="muted">Who did what, when, on which shop, from which IP, and the outcome.</p></div></div>
<form class="filters-bar" method="get"><label class="sr" for="aa">Action</label><input id="aa" name="action" value="<?= e(get('action')) ?>" placeholder="Action contains… (e.g. login, tenant, product)"><label class="sr" for="ao">Outcome</label><select id="ao" name="outcome"><option value="">Any outcome</option><?php foreach (['success', 'failure', 'denied'] as $o): ?><option <?= get('outcome') === $o ? 'selected' : '' ?>><?= $o ?></option><?php endforeach ?></select><?php if (int_in('shop_id')): ?><input type="hidden" name="shop_id" value="<?= int_in('shop_id') ?>"><?php endif ?><button class="btn btn-sm">Filter</button></form>
<div class="table-wrap"><table class="table small"><thead><tr><th>When</th><th>Actor</th><th>Shop</th><th>Action</th><th>Entity</th><th>Outcome</th><th>IP</th><th>Details</th></tr></thead><tbody>
<?php foreach ($logs as $a): ?><tr><td><?= e(fmt_date($a['created_at'], true)) ?></td><td><?= e($a['actor_email']) ?><?= $a['impersonator_id'] ? ' <span class="badge badge-warn">as shop</span>' : '' ?></td><td><?= $a['shop_id'] ? '<a href="/superadmin/shops/' . (int) $a['shop_id'] . '/">' . e($a['shop_name'] ?? '#' . $a['shop_id']) . '</a>' : '—' ?></td><td class="mono"><?= e($a['action']) ?></td><td><?= e(trim($a['entity_type'] . ' ' . $a['entity_id'])) ?></td><td><span class="badge badge-<?= $a['outcome'] === 'success' ? 'ok' : 'bad' ?>"><?= e($a['outcome']) ?></span></td><td class="mono"><?= e($a['ip']) ?></td><td class="mono"><?= e(str_limit((string) $a['details'], 80)) ?></td></tr><?php endforeach ?>
</tbody></table></div><?= pager_html($pg, '/superadmin/audit/') ?>
